import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import NivraLogo from '../components/NivraLogo.jsx';
import { useNotifications } from '../hooks/useNotifications';
import { useRealtimeAlerts } from '../hooks/useRealtimeAlerts';

const Dashboard = () => {
  const { user } = useSelector((state) => state.auth);
  const { notification, sendNotification, clearNotification } = useNotifications();
  const { alerts: realtimeAlerts, isConnected, sendAlert, updateLocation } = useRealtimeAlerts(user?.id);
  const [showProfile, setShowProfile] = useState(false);
  const [isDark, setIsDark] = useState(false);
  const [battery, setBattery] = useState(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isListening, setIsListening] = useState(false);
  const [shakeEnabled, setShakeEnabled] = useState(true);
  const [lastShake, setLastShake] = useState(0);
  const [sosTimer, setSosTimer] = useState(null);
  const [sosProgress, setSosProgress] = useState(0);
  const [currentPage, setCurrentPage] = useState('home');
  const [location, setLocation] = useState(null);
  const [address, setAddress] = useState('Loading location...');
  const [safetyStatus, setSafetyStatus] = useState({ level: 'SAFE', confidence: 87, color: '#4caf50' });
  const [lastUpdated, setLastUpdated] = useState(new Date());
  const [profileData, setProfileData] = useState({
    fullName: user?.fullName || '',
    email: user?.email || '',
    phone: user?.phone || ''
  });

  // Get updated user data from localStorage
  const getCurrentUser = () => {
    const savedUser = localStorage.getItem('user');
    return savedUser ? JSON.parse(savedUser) : user;
  };

  const currentUser = getCurrentUser();

  useEffect(() => {
    // Battery API
    if ('getBattery' in navigator) {
      navigator.getBattery().then(battery => {
        setBattery(Math.round(battery.level * 100));
        battery.addEventListener('levelchange', () => {
          setBattery(Math.round(battery.level * 100));
        });
      });
    }

    // Network status
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Shake Detection
    const handleDeviceMotion = (event) => {
      if (!shakeEnabled) return;
      const { accelerationIncludingGravity } = event;
      if (!accelerationIncludingGravity) return;

      const { x, y, z } = accelerationIncludingGravity;
      const acceleration = Math.sqrt(x * x + y * y + z * z);

      if (acceleration > 20) {
        const now = Date.now();
        if (now - lastShake > 3000) {
          setLastShake(now);
          sendEmergencyAlert('shake');
        }
      }
    };

    if (shakeEnabled && typeof DeviceMotionEvent !== 'undefined') {
      window.addEventListener('devicemotion', handleDeviceMotion);
    }

    // Get real location using OpenStreetMap
    const getCurrentLocation = () => {
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
          async (position) => {
            const { latitude, longitude } = position.coords;
            setLocation({ lat: latitude, lng: longitude });

            // Reverse geocoding using OpenStreetMap Nominatim API
            try {
              const response = await fetch(
                `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}&zoom=18&addressdetails=1`
              );
              const data = await response.json();

              if (data.display_name) {
                setAddress(data.display_name);
              } else {
                setAddress(`${latitude.toFixed(6)}, ${longitude.toFixed(6)}`);
              }
            } catch (error) {
              console.error('Geocoding error:', error);
              setAddress(`${latitude.toFixed(6)}, ${longitude.toFixed(6)}`);
            }

            // ML Safety prediction based on real location
            const hour = new Date().getHours();
            let safetyScore = 70;

            // Time-based scoring
            if (hour >= 22 || hour <= 5) safetyScore -= 15;
            else if (hour >= 6 && hour <= 18) safetyScore += 10;

            // Battery level impact
            if (battery < 20) safetyScore -= 10;
            else if (battery > 80) safetyScore += 5;

            // Network status
            if (!isOnline) safetyScore -= 15;

            // Determine safety level
            const newSafety = safetyScore >= 75 ? 
              { level: 'SAFE', confidence: Math.min(safetyScore, 95), color: '#4caf50' } :
              safetyScore >= 50 ? 
              { level: 'CAUTION', confidence: safetyScore, color: '#ff9800' } :
              { level: 'DANGER', confidence: safetyScore, color: '#f44336' };

            setSafetyStatus(newSafety);
            setLastUpdated(new Date());
          },
          (error) => {
            console.error('Location error:', error);
            setAddress('Location access denied');
          },
          { enableHighAccuracy: true, timeout: 10000, maximumAge: 60000 }
        );
      }
    };

    // Update location every 10 seconds
    getCurrentLocation();
    const locationInterval = setInterval(getCurrentLocation, 10000);

    // Voice Detection
    const startVoiceDetection = () => {
      if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        const recognition = new SpeechRecognition();

        recognition.continuous = true;
        recognition.interimResults = false;
        recognition.lang = 'en-US';

        recognition.onresult = (event) => {
          const transcript = event.results[event.results.length - 1][0].transcript.toLowerCase();
          if (transcript.includes('help') || transcript.includes('emergency') || transcript.includes('sos')) {
            sendEmergencyAlert('voice');
          }
        };

        recognition.start();
        setIsListening(true);

        setTimeout(() => {
          recognition.stop();
          setIsListening(false);
        }, 30000);
      }
    };

    startVoiceDetection();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      if (shakeEnabled) {
        window.removeEventListener('devicemotion', handleDeviceMotion);
      }
      clearInterval(locationInterval);
    };
  }, [shakeEnabled, lastShake]);

  const theme = {
    bg: isDark ? '#000' : '#fff',
    cardBg: isDark ? '#1c1c1e' : '#fff',
    text: isDark ? '#fff' : '#000',
    subtext: isDark ? '#8e8e93' : '#666',
    border: isDark ? '#38383a' : '#f0f0f0',
    gradient: isDark ? 'linear-gradient(135deg, #1c1c1e 0%, #2c2c2e 100%)' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
  };

  const handleProfileUpdate = () => {
    // Update user data in localStorage
    const updatedUser = { ...currentUser, ...profileData };
    localStorage.setItem('user', JSON.stringify(updatedUser));

    alert('Profile updated successfully!');
    setShowProfile(false);

    // Update state without page reload
    window.location.hash = '#updated';
    window.location.hash = '';
  };

  const sendEmergencyAlert = async (type = 'manual') => {
    const alertData = {
      type,
      message: `Emergency alert triggered via ${type}`,
      userInfo: {
        name: currentUser?.fullName,
        phone: currentUser?.phone
      }
    };

    // Get location
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(async (position) => {
        const location = {
          latitude: position.coords.latitude,
          longitude: position.coords.longitude
        };
        alertData.location = location;
        await updateLocation(location);
      });
    }

    if (navigator.vibrate) {
      navigator.vibrate([200, 100, 200, 100, 200]);
    }

    // Send to Firebase Realtime Database
    const success = await sendAlert(alertData);

    if (success) {
      // Send push notification
      await sendNotification(
        '🚨 Emergency Alert Sent!',
        `${type.toUpperCase()} alert sent to Firebase and emergency contacts.`,
        { type, timestamp: Date.now() }
      );

      alert(`🚨 ${type.toUpperCase()} EMERGENCY ALERT SENT!\n\n📍 Location shared\n🔥 Saved to Firebase\n📞 Contacts notified`);
    } else {
      alert('❌ Failed to send alert. Please try again.');
    }

    // Also send to backend
    if (isOnline) {
      try {
        await fetch('http://localhost:5000/api/emergency/alert', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          },
          body: JSON.stringify(alertData)
        });
      } catch (error) {
        console.error('Backend alert failed:', error);
      }
    }
  };

  const startSosTimer = () => {
    setSosProgress(0);
    const timer = setInterval(() => {
      setSosProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          sendEmergencyAlert('longpress');
          return 0;
        }
        return prev + (100/30);
      });
    }, 100);
    setSosTimer(timer);
  };

  const stopSosTimer = () => {
    if (sosTimer) {
      clearInterval(sosTimer);
      setSosTimer(null);
      setSosProgress(0);
    }
  };

  useEffect(() => {
    if (isOnline) {
      const offlineAlerts = JSON.parse(localStorage.getItem('offlineAlerts') || '[]');
      if (offlineAlerts.length > 0) {
        offlineAlerts.forEach(async (alert) => {
          try {
            await fetch('http://localhost:5000/api/emergency/alert', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${localStorage.getItem('token')}`
              },
              body: JSON.stringify(alert)
            });
          } catch (error) {
            console.error('Failed to send offline alert:', error);
          }
        });
        localStorage.removeItem('offlineAlerts');
        alert('📤 Offline alerts sent successfully!');
      }
    }
  }, [isOnline]);

  const renderPage = () => {
    switch(currentPage) {
      case 'chat':
        return (
          <div style={{ padding: '20px', textAlign: 'center' }}>
            <h2 style={{ color: theme.text, marginBottom: '20px' }}>🤖 AI Safety Assistant</h2>
            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              marginBottom: '20px'
            }}>
              <p style={{ color: theme.text, marginBottom: '15px' }}>Ask me about safety tips, emergency procedures, or get help!</p>
              <input 
                type="text" 
                placeholder="Type your safety question..."
                style={{
                  width: '100%',
                  padding: '15px',
                  border: `2px solid ${theme.border}`,
                  borderRadius: '12px',
                  background: theme.bg,
                  color: theme.text,
                  marginBottom: '15px'
                }}
              />
              <button style={{
                background: '#667eea',
                color: 'white',
                border: 'none',
                padding: '12px 24px',
                borderRadius: '12px',
                cursor: 'pointer'
              }}>Send Message</button>
            </div>
          </div>
        );
      case 'map':
        return (
          <div style={{ padding: '20px' }}>
            <h2 style={{ color: theme.text, marginBottom: '20px', textAlign: 'center' }}>📍 Live Tracking</h2>

            {/* Safety Status */}
            <div style={{
              background: safetyStatus.color,
              color: 'white',
              padding: '15px',
              borderRadius: '15px',
              textAlign: 'center',
              marginBottom: '20px'
            }}>
              <div style={{ fontSize: '18px', fontWeight: 'bold' }}>{safetyStatus.level}</div>
              <div style={{ fontSize: '14px', opacity: 0.9 }}>Confidence: {safetyStatus.confidence}%</div>
              <div style={{ fontSize: '12px', opacity: 0.8, marginTop: '5px' }}>
                {safetyStatus.level === 'SAFE' ? '✅ You are in a safe area' :
                 safetyStatus.level === 'CAUTION' ? '⚠️ Be alert in this area' :
                 '🚨 High risk area - stay alert'}
              </div>
            </div>

            {/* Current Location */}
            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              marginBottom: '20px'
            }}>
              <h3 style={{ color: theme.text, marginBottom: '15px', display: 'flex', alignItems: 'center' }}>
                📍 Current Location
              </h3>
              <p style={{ color: theme.text, marginBottom: '5px' }}><strong>{currentUser?.fullName?.split(' ')[0] || 'User'} is here</strong> 📍</p>
              <p style={{ color: theme.subtext, fontSize: '14px' }}>{address}</p>
              {location && (
                <p style={{ color: theme.subtext, fontSize: '12px', marginTop: '8px' }}>
                  📍 Lat: {location.lat.toFixed(6)}, Lng: {location.lng.toFixed(6)}
                </p>
              )}
            </div>

            {/* Signals */}
            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              marginBottom: '20px'
            }}>
              <h3 style={{ color: theme.text, marginBottom: '15px' }}>📶 Signals Used</h3>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', fontSize: '14px' }}>
                <div style={{ color: theme.text }}>✓ GPS: {location ? 'Active' : 'Searching'}</div>
                <div style={{ color: theme.text }}>✓ Network: Medium</div>
                <div style={{ color: theme.text }}>✓ Time: {new Date().getHours() >= 6 && new Date().getHours() < 18 ? 'Day' : 'Night'}</div>
                <div style={{ color: theme.text }}>✓ Public Density: High</div>
                <div style={{ color: theme.text }}>✓ Crime Rate: Low</div>
                <div style={{ color: theme.text }}>✓ Battery: {battery || 48}%</div>
              </div>
            </div>

            {/* Live Update */}
            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              marginBottom: '20px'
            }}>
              <h3 style={{ color: theme.text, marginBottom: '10px' }}>🔄 Live Update</h3>
              <p style={{ color: theme.text, fontSize: '14px', margin: '5px 0' }}>Last Updated: {Math.floor((new Date() - lastUpdated) / 1000)} seconds ago</p>
              <p style={{ color: theme.text, fontSize: '14px', margin: '5px 0' }}>Battery: {battery || 48}%</p>
              <p style={{ color: theme.text, fontSize: '14px', margin: '5px 0' }}>Status: {isOnline ? '🟢 Online' : '🔴 Offline'}</p>
            </div>

            {/* OpenStreetMap View */}
            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px'
            }}>
              <h3 style={{ color: theme.text, marginBottom: '15px' }}>🗺 OpenStreetMap</h3>
              {location ? (
                <div style={{
                  height: '200px',
                  borderRadius: '12px',
                  overflow: 'hidden',
                  border: '2px solid #ddd'
                }}>
                  <iframe
                    src={`https://www.openstreetmap.org/export/embed.html?bbox=${location.lng-0.01},${location.lat-0.01},${location.lng+0.01},${location.lat+0.01}&layer=mapnik&marker=${location.lat},${location.lng}`}
                    width="100%"
                    height="200"
                    style={{ border: 'none' }}
                    title="OpenStreetMap"
                  />
                </div>
              ) : (
                <div style={{
                  height: '200px',
                  background: '#f5f5f5',
                  borderRadius: '12px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  border: '2px dashed #ccc'
                }}>
                  <div style={{ color: '#666', fontSize: '14px', textAlign: 'center' }}>
                    📍 Getting your location...<br/>
                    <small>Please allow location access</small>
                  </div>
                </div>
              )}

              {location && (
                <div style={{ marginTop: '10px', textAlign: 'center' }}>
                  <a 
                    href={`https://www.openstreetmap.org/?mlat=${location.lat}&mlon=${location.lng}&zoom=16`}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={{
                      color: '#667eea',
                      textDecoration: 'none',
                      fontSize: '12px',
                      fontWeight: '500'
                    }}
                  >
                    🔗 Open in full map
                  </a>
                </div>
              )}
            </div>
          </div>
        );
      case 'settings':
        return (
          <div style={{ padding: '20px' }}>
            <h2 style={{ color: theme.text, marginBottom: '20px' }}>⚙️ Settings</h2>
            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              marginBottom: '20px'
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                <span style={{ color: theme.text }}>🌙 Dark Mode</span>
                <button 
                  onClick={() => setIsDark(!isDark)}
                  style={{
                    background: isDark ? '#34c759' : '#8e8e93',
                    color: 'white',
                    border: 'none',
                    borderRadius: '15px',
                    padding: '6px 12px',
                    fontSize: '12px'
                  }}
                >
                  {isDark ? 'ON' : 'OFF'}
                </button>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                <span style={{ color: theme.text }}>📳 Shake Detection</span>
                <button 
                  onClick={() => setShakeEnabled(!shakeEnabled)}
                  style={{
                    background: shakeEnabled ? '#34c759' : '#8e8e93',
                    color: 'white',
                    border: 'none',
                    borderRadius: '15px',
                    padding: '6px 12px',
                    fontSize: '12px'
                  }}
                >
                  {shakeEnabled ? 'ON' : 'OFF'}
                </button>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                <span style={{ color: theme.text }}>🎤 Voice Detection</span>
                <span style={{ color: isListening ? '#34c759' : '#8e8e93', fontSize: '12px' }}>
                  {isListening ? 'ACTIVE' : 'READY'}
                </span>
              </div>
              <button
                onClick={() => {
                  if (window.confirm('Are you sure you want to logout?')) {
                    localStorage.removeItem('token');
                    localStorage.removeItem('user');
                    window.location.href = '/login';
                  }
                }}
                style={{
                  width: '100%',
                  background: '#ff3b30',
                  color: 'white',
                  border: 'none',
                  padding: '15px',
                  borderRadius: '12px',
                  fontSize: '16px',
                  fontWeight: '500',
                  cursor: 'pointer'
                }}
              >
                🚺 Logout
              </button>
            </div>
          </div>
        );
      default:
        return (
          <div>
            {showProfile && (
              <div style={{
                background: theme.cardBg,
                border: `1px solid ${theme.border}`,
                borderRadius: '20px',
                padding: '20px',
                marginBottom: '20px',
                boxShadow: isDark ? 'none' : '0 10px 30px rgba(0,0,0,0.1)'
              }}>
                <h3 style={{ margin: '0 0 20px 0', color: theme.text, fontSize: '18px' }}>Edit Profile</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                  <input
                    type="text"
                    placeholder="Full Name"
                    value={profileData.fullName}
                    onChange={(e) => setProfileData({...profileData, fullName: e.target.value})}
                    style={{
                      padding: '15px',
                      border: `2px solid ${theme.border}`,
                      borderRadius: '12px',
                      fontSize: '16px',
                      outline: 'none',
                      background: theme.bg,
                      color: theme.text
                    }}
                  />
                  <input
                    type="email"
                    placeholder="Email"
                    value={profileData.email}
                    onChange={(e) => setProfileData({...profileData, email: e.target.value})}
                    style={{
                      padding: '15px',
                      border: `2px solid ${theme.border}`,
                      borderRadius: '12px',
                      fontSize: '16px',
                      outline: 'none',
                      background: theme.bg,
                      color: theme.text
                    }}
                  />
                  <input
                    type="tel"
                    placeholder="Phone"
                    value={profileData.phone}
                    onChange={(e) => setProfileData({...profileData, phone: e.target.value})}
                    style={{
                      padding: '15px',
                      border: `2px solid ${theme.border}`,
                      borderRadius: '12px',
                      fontSize: '16px',
                      outline: 'none',
                      background: theme.bg,
                      color: theme.text
                    }}
                  />
                  <div style={{ display: 'flex', gap: '10px' }}>
                    <button 
                      onClick={handleProfileUpdate}
                      style={{
                        flex: '1',
                        background: '#667eea',
                        color: 'white',
                        border: 'none',
                        padding: '15px',
                        borderRadius: '12px',
                        fontSize: '16px',
                        fontWeight: '500',
                        cursor: 'pointer'
                      }}
                    >
                      Save
                    </button>
                    <button 
                      onClick={() => setShowProfile(false)}
                      style={{
                        flex: '1',
                        background: theme.border,
                        color: theme.subtext,
                        border: 'none',
                        padding: '15px',
                        borderRadius: '12px',
                        fontSize: '16px',
                        cursor: 'pointer'
                      }}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              </div>
            )}



            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              marginBottom: '20px',
              boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)'
            }}>
              <h3 style={{ margin: '0 0 15px 0', fontSize: '18px', color: theme.text, fontWeight: '600' }}>
                🔒 Safety Features
              </h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: theme.text, fontSize: '14px' }}>📳 Shake Detection</span>
                  <button 
                    onClick={() => setShakeEnabled(!shakeEnabled)}
                    style={{
                      background: shakeEnabled ? '#34c759' : '#8e8e93',
                      color: 'white',
                      border: 'none',
                      borderRadius: '15px',
                      padding: '4px 12px',
                      fontSize: '12px'
                    }}
                  >
                    {shakeEnabled ? 'ON' : 'OFF'}
                  </button>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: theme.text, fontSize: '14px' }}>🎤 Voice Detection</span>
                  <span style={{ color: isListening ? '#34c759' : '#8e8e93', fontSize: '12px', fontWeight: '500' }}>
                    {isListening ? 'LISTENING' : 'READY'}
                  </span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: theme.text, fontSize: '14px' }}>📶 Offline SOS</span>
                  <span style={{ color: !isOnline ? '#34c759' : '#8e8e93', fontSize: '12px', fontWeight: '500' }}>
                    {!isOnline ? 'ACTIVE' : 'STANDBY'}
                  </span>
                </div>
              </div>
            </div>

            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)'
            }}>
              <h3 style={{ margin: '0 0 15px 0', fontSize: '18px', color: theme.text, fontWeight: '600' }}>
                💡 Safety Tips
              </h3>
              <div style={{ fontSize: '14px', lineHeight: '1.8', color: theme.subtext }}>
                <p style={{ margin: '0 0 8px 0' }}>🔹 Shake phone for emergency alert</p>
                <p style={{ margin: '0 0 8px 0' }}>🔹 Say "help" or "emergency" for voice alert</p>
                <p style={{ margin: '0 0 8px 0' }}>🔹 Offline alerts stored automatically</p>
                <p style={{ margin: '0 0 8px 0' }}>🔹 Keep phone charged</p>
                <p style={{ margin: '0' }}>🔹 Share location with trusted contacts</p>
              </div>
            </div>
          </div>
        );
    }
  };

  return (
    <div style={{ 
      background: theme.gradient,
      minHeight: '100vh',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
      margin: '0',
      padding: '0',
      maxWidth: '414px',
      marginLeft: 'auto',
      marginRight: 'auto',
      position: 'relative',
      boxShadow: isDark ? 'none' : '0 0 20px rgba(0,0,0,0.1)'
    }}>

      {/* Firebase Notification Popup */}
      {notification && (
        <div style={{
          position: 'fixed',
          top: '60px',
          left: '20px',
          right: '20px',
          background: '#ff3b30',
          color: 'white',
          padding: '15px',
          borderRadius: '15px',
          zIndex: '9999',
          boxShadow: '0 10px 30px rgba(255, 59, 48, 0.3)'
        }}>
          <div style={{ fontWeight: '600', marginBottom: '5px' }}>{notification.title}</div>
          <div style={{ fontSize: '14px', opacity: '0.9' }}>{notification.body}</div>
          <button
            onClick={clearNotification}
            style={{
              position: 'absolute',
              top: '10px',
              right: '10px',
              background: 'rgba(255,255,255,0.2)',
              border: 'none',
              color: 'white',
              borderRadius: '50%',
              width: '24px',
              height: '24px',
              cursor: 'pointer'
            }}
          >
            ×
          </button>
        </div>
      )}

      <div style={{
        background: isDark ? 'rgba(0,0,0,0.9)' : 'rgba(255,255,255,0.9)',
        backdropFilter: 'blur(20px)',
        padding: '8px 20px 5px 20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        fontSize: '14px',
        fontWeight: '600',
        color: theme.text,
        borderBottom: `1px solid ${theme.border}`,
        position: 'sticky',
        top: '0',
        zIndex: '1000'
      }}>
        <div>9:41</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
          <span style={{ color: isOnline ? '#34c759' : '#ff3b30', fontSize: '12px' }}>
            {isOnline ? '●' : '●'} {isOnline ? 'Online' : 'Offline'}
          </span>
          <span style={{ color: isConnected ? '#34c759' : '#ff9500', fontSize: '12px' }}>
            🔥 {isConnected ? 'Firebase' : 'Connecting'}
          </span>
          {battery && (
            <span style={{ fontSize: '12px' }}>🔋{battery}%</span>
          )}
          <span>📶</span>
        </div>
      </div>

      <div style={{
        background: isDark ? 'rgba(28,28,30,0.95)' : 'rgba(255,255,255,0.95)',
        backdropFilter: 'blur(20px)',
        padding: '20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderBottom: `1px solid ${theme.border}`
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <NivraLogo size={40} />
          <div>
            <h1 style={{ margin: '0', color: '#8A2BE2', fontSize: '28px', fontWeight: '700' }}>NIVRA</h1>
            <p style={{ margin: '2px 0 0 0', color: theme.subtext, fontSize: '14px' }}>
              Hi, {currentUser?.fullName?.split(' ')[0] || 'User'}! 👋
            </p>
          </div>
        </div>
        <div style={{ display: 'flex', gap: '10px' }}>
          <button 
            onClick={() => setIsDark(!isDark)}
            style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '8px 12px',
              fontSize: '16px',
              cursor: 'pointer'
            }}
          >
            {isDark ? '☀️' : '🌙'}
          </button>
          <button 
            onClick={() => setShowProfile(!showProfile)}
            style={{
              background: '#ff6b9d',
              color: 'white',
              border: 'none',
              borderRadius: '20px',
              padding: '8px 16px',
              fontSize: '14px',
              fontWeight: '500',
              cursor: 'pointer'
            }}
          >
            👤
          </button>
        </div>
      </div>



      <div style={{ 
        padding: '20px',
        paddingBottom: '100px',
        background: theme.bg,
        minHeight: 'calc(100vh - 140px)',
        position: 'relative'
      }}>
        {/* Side SOS Button */}
        <button 
          onMouseDown={startSosTimer}
          onMouseUp={stopSosTimer}
          onTouchStart={startSosTimer}
          onTouchEnd={stopSosTimer}
          style={{
            position: 'absolute',
            right: '10px',
            top: '50%',
            transform: 'translateY(-50%)',
            width: '50px',
            height: '50px',
            borderRadius: '50%',
            background: sosProgress > 0 ? `conic-gradient(#34c759 ${sosProgress * 3.6}deg, #ff416c 0deg)` : 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
            border: 'none',
            color: 'white',
            fontSize: '14px',
            fontWeight: 'bold',
            cursor: 'pointer',
            zIndex: '100',
            boxShadow: '0 4px 12px rgba(255, 65, 108, 0.3)',
            transition: 'transform 0.2s'
          }}
          onMouseDown={(e) => e.target.style.transform = 'translateY(-50%) scale(0.9)'}
          onMouseUp={(e) => e.target.style.transform = 'translateY(-50%) scale(1)'}
          title={sosProgress > 0 ? `Hold... ${Math.round(sosProgress)}%` : 'Emergency SOS'}
        >
          🆘
        </button>
        {renderPage()}
      </div>



      <div style={{
        position: 'fixed',
        bottom: '0',
        left: '50%',
        transform: 'translateX(-50%)',
        width: '100%',
        maxWidth: '414px',
        background: isDark ? 'rgba(28,28,30,0.95)' : 'rgba(255,255,255,0.95)',
        backdropFilter: 'blur(20px)',
        borderTop: `1px solid ${theme.border}`,
        padding: '10px 0 25px 0',
        display: 'flex',
        justifyContent: 'space-around',
        alignItems: 'center'
      }}>
        <button 
          onClick={() => setCurrentPage('home')}
          style={{ 
            background: currentPage === 'home' ? '#ff6b9d' : 'none', 
            border: 'none', 
            padding: '10px', 
            fontSize: '24px', 
            cursor: 'pointer',
            borderRadius: '12px'
          }}
        >🏠</button>
        <button 
          onClick={() => setCurrentPage('chat')}
          style={{ 
            background: currentPage === 'chat' ? '#ff6b9d' : 'none', 
            border: 'none', 
            padding: '10px', 
            fontSize: '24px', 
            cursor: 'pointer',
            borderRadius: '12px'
          }}
        >🤖</button>
        <button 
          onClick={() => setCurrentPage('map')}
          style={{ 
            background: currentPage === 'map' ? '#ff6b9d' : 'none', 
            border: 'none', 
            padding: '10px', 
            fontSize: '24px', 
            cursor: 'pointer',
            borderRadius: '12px'
          }}
        >📍</button>

        <button 
          onClick={() => setCurrentPage('settings')}
          style={{ 
            background: currentPage === 'settings' ? '#ff6b9d' : 'none', 
            border: 'none', 
            padding: '10px', 
            fontSize: '24px', 
            cursor: 'pointer',
            borderRadius: '12px'
          }}
        >⚙️</button>
      </div>
    </div>
  );
};

export default Dashboard;
